#include <iostream>
#include <algorithm>
#include <cstdio>
using namespace std;

int main() {
    char s[3], a[3];
    int n;

    while (scanf("%2s", s) == 1) {
        if (scanf("%d", &n) != 1) break;

        char A = s[0];
        char B = s[1];

        if (n == 1) {
            scanf("%2s", a);
            sort(a, a + 2);
            if (a[0] == A && a[1] == B)
                cout << "YES" << endl;
            continue;
        }

        int flag1 = 0;
        int flag2 = 0;

        for (int i = 1; i <= n; i++) {
            scanf("%2s", a);
            if (a[0] == B)
                flag1 = 1;
            if (A == a[1])
                flag2 = 1;
        }

        if (flag1 && flag2)
            cout << "YES" << endl;
        else
            cout << "NO" << endl;
    }

    return 0;
}

