    cin.tie(nullptr);

    string s;
    int n;

    while (cin >> s >> n) {
        bool exact = false;
        bool left = false;
        bool right = false;

        for (int i = 0; i < n; ++i) {
            string a;
            cin >> a;

            if (a == s)
                exact = true;
            if (a[1] == s[0])
                left = true;
            if (a[0] == s[1])
                right = true;
        }

        cout << (exact || (left && right) ? "YES\n" : "NO\n");
    }

    return 0;
}

